-- Disposable synthetic ACL test; no network/live credentials.
-- Vector values use double precision[]: this tests authorization, not pgvector math.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
CREATE FUNCTION assert_ok(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL %',label; END IF; RAISE NOTICE 'PASS %',label; END $$;
CREATE FUNCTION assert_denied(q text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS %',label; RETURN; END; RAISE EXCEPTION 'FAIL expected 42501 %',label; END $$;
CREATE TABLE mantas(manta_uuid uuid,fk_catalog_uuid uuid);
CREATE TABLE catalog(catalog_uuid uuid,name text);
CREATE TABLE manta_embeddings(fk_manta_id integer PRIMARY KEY,photo_id_int integer NOT NULL,embedding double precision[],updated_at timestamptz DEFAULT now(),true_catalog_id integer,true_match_rank integer,match_score double precision,fk_manta_uuid uuid,photo_id uuid);
CREATE TABLE photo_embeddings(photo_id uuid PRIMARY KEY,embedding double precision[],created_at timestamptz DEFAULT now(),side text DEFAULT 'ventral',storage_path text);
INSERT INTO manta_embeddings(fk_manta_id,photo_id_int,embedding) VALUES(1,37,ARRAY[1.0]);
INSERT INTO photo_embeddings(photo_id,embedding) VALUES('00000000-0000-4000-8000-000000000037',ARRAY[1.0]);
CREATE VIEW vw_manta_embeddings_uuid AS  SELECT me.fk_manta_uuid,
    me.photo_id_int AS photo_id,
    me.embedding,
    me.updated_at,
    m.manta_uuid,
    m.fk_catalog_uuid,
    c.catalog_uuid,
    c.name AS catalog_name
   FROM manta_embeddings me
     LEFT JOIN mantas m ON me.fk_manta_uuid = m.manta_uuid
     LEFT JOIN catalog c ON m.fk_catalog_uuid = c.catalog_uuid;
GRANT SELECT,INSERT,UPDATE,DELETE ON manta_embeddings,photo_embeddings TO authenticated;
-- Explicit live seven-privilege baseline; PostgreSQL 17 ALL also adds MAINTAIN.
GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON vw_manta_embeddings_uuid TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON manta_embeddings,photo_embeddings,vw_manta_embeddings_uuid TO service_role;
-- Restricted invoker reader models prove execution-role semantics; not vector ranking.
CREATE FUNCTION fixture_read_embeddings() RETURNS integer LANGUAGE sql AS $$ SELECT (SELECT count(*) FROM manta_embeddings)+(SELECT count(*) FROM photo_embeddings) $$;
REVOKE ALL ON FUNCTION fixture_read_embeddings() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fixture_read_embeddings() TO service_role;
CREATE TABLE baseline_acl AS SELECT c.relname,a.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid IN ('manta_embeddings'::regclass,'photo_embeddings'::regclass,'vw_manta_embeddings_uuid'::regclass);
CREATE FUNCTION shape() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',c.relowner,'rls',c.relrowsecurity,'options',c.reloptions,'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY attnum) FROM pg_attribute a WHERE a.attrelid=c.oid),'view',CASE WHEN c.relkind='v' THEN pg_get_viewdef(c.oid,true) END) ORDER BY c.relname) FROM pg_class c WHERE c.oid IN ('manta_embeddings'::regclass,'photo_embeddings'::regclass,'vw_manta_embeddings_uuid'::regclass) $$;
CREATE FUNCTION content() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('manta',(SELECT jsonb_agg(to_jsonb(t) ORDER BY fk_manta_id) FROM manta_embeddings t),'photo',(SELECT jsonb_agg(to_jsonb(t) ORDER BY photo_id) FROM photo_embeddings t)) $$;
CREATE TABLE baseline AS SELECT shape() definition,content() contents;
-- Deployed manta writer omits required photo_id_int. Capture its pre-existing failure.
CREATE FUNCTION assert_writer_mismatch() RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN
INSERT INTO manta_embeddings(fk_manta_id,photo_id,embedding,updated_at) VALUES(2,'00000000-0000-4000-8000-000000000038',ARRAY[1.0],now()) ON CONFLICT(fk_manta_id) DO UPDATE SET embedding=excluded.embedding;
EXCEPTION WHEN not_null_violation THEN RAISE NOTICE 'PASS deployed manta payload has pre-existing NOT NULL mismatch'; RETURN;
END; RAISE EXCEPTION 'Expected existing payload mismatch'; END $$;
SET ROLE service_role;
SELECT assert_writer_mismatch();
RESET ROLE;
