SELECT assert_writer_mismatch();
BEGIN;
INSERT INTO manta_embeddings(fk_manta_id,photo_id_int,embedding) VALUES(2,38,ARRAY[1.0]) ON CONFLICT(fk_manta_id) DO UPDATE SET embedding=excluded.embedding;
UPDATE manta_embeddings SET embedding=ARRAY[2.0] WHERE fk_manta_id=2;
DELETE FROM manta_embeddings WHERE fk_manta_id=2;
INSERT INTO photo_embeddings(photo_id,embedding) VALUES('00000000-0000-4000-8000-000000000038',ARRAY[1.0]) ON CONFLICT(photo_id) DO UPDATE SET embedding=excluded.embedding;
UPDATE photo_embeddings SET embedding=ARRAY[2.0] WHERE photo_id='00000000-0000-4000-8000-000000000038';
DELETE FROM photo_embeddings WHERE photo_id='00000000-0000-4000-8000-000000000038';
SELECT assert_ok(true,'reapply service write paths succeed');
ROLLBACK;
RESET ROLE;
SELECT assert_ok(shape()=(SELECT definition FROM baseline),'reapply definition owner RLS unchanged');
SELECT assert_ok(content()=(SELECT contents FROM baseline),'reapply content unchanged');
SELECT assert_ok(NOT EXISTS((SELECT c.relname,a.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid IN ('manta_embeddings'::regclass,'photo_embeddings'::regclass,'vw_manta_embeddings_uuid'::regclass) AND a.grantee='service_role'::regrole) EXCEPT SELECT * FROM baseline_acl WHERE grantee='service_role'::regrole),'reapply service ACL unchanged');
